/* Make the div a flex container */
.flex-container {
  display: flex;
  /* Other properties can be added here */
  background-color: #f0f0f0;
  height: 200px;
  align-items: center; /*Vertical alignment*/
  justify-content: center; /*Horizontal alignment*/
}

/* Example flex item style */
.flex-item {
  width: 100px;
  height: 50px;
  background-color: #3498db;
  color: white;
  text-align: center;
  line-height: 50px;
}

/* Style for individual flex items */
.flex-item {
  width: 100px;
  height: 50px;
  background-color: #e74c3c;
  color: white;
  text-align: center;
  line-height: 50px;
  margin: 5px;
  /* Flex properties can be added here */
  flex-grow: 1; /* Allow item to grow and fill available space */
}

/* Change the main axis direction */
.flex-container {
  display: flex;
  flex-direction: column; /* Vertical layout */
  height: 300px;
}

.flex-item {
  width: 80%;
  margin: 5px;
  background-color: #2ecc71;
  color: white;
  text-align: center;
  line-height: 50px;
}

/* Enable wrapping of flex items */
.flex-container {
  display: flex;
  flex-wrap: wrap; /* Allow items to wrap */
  width: 300px;
}

.flex-item {
  width: 100px;
  height: 50px;
  background-color: #9b59b6;
  color: white;
  text-align: center;
  line-height: 50px;
  margin: 5px;
}

/* Align items vertically to the center */
.flex-container {
  display: flex;
  align-items: center; /* Vertical alignment */
  height: 200px;
  background-color: #f0f0f0;
}

.flex-item {
  width: 100px;
  height: 50px;
  background-color: #3498db;
  color: white;
  text-align: center;
  line-height: 50px;
  margin: 5px;
}

/* Distribute items with space between */
.flex-container {
  display: flex;
  justify-content: space-between; /* Horizontal spacing */
  width: 500px;
  background-color: #f0f0f0;
}

.flex-item {
  width: 100px;
  height: 50px;
  background-color: #e74c3c;
  color: white;
  text-align: center;
  line-height: 50px;
  margin: 5px;
}

/* Reorder flex items */
.item1 {
  order: 3; /* Move to the end */
}

.item2 {
  order: 1; /* Move to the beginning */
}

.item3 {
  order: 2; /* Keep in the middle */
}

/* Set initial item size */
.flex-item {
  flex-basis: 200px; /* Initial width of 200px */
  height: 50px;
  background-color: #2ecc71;
  color: white;
  text-align: center;
  line-height: 50px;
  margin: 5px;
}

/* Allow items to grow and shrink */
.flex-item {
  flex-grow: 1; /* Grow to fill available space */
  flex-shrink: 1; /* Shrink if needed */
  width: 100px;
  height: 50px;
  background-color: #9b59b6;
  color: white;
  text-align: center;
  line-height: 50px;
  margin: 5px;
}
